package app.launcherin.tv;
import android.content.Context;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;
/** Bounded circular artwork + measured FFT. Choreographer is owned by visibility and playback. */
final class LauncherinCircularView extends FrameLayout implements Choreographer.FrameCallback {
 final ImageView cover;private final Ring ring;private final LauncherinAudioSpectrum spectrum=new LauncherinAudioSpectrum();private final float[] target=new float[48],smooth=new float[48];
 private LauncherinVisualOptions options;private boolean active,playing,minimal,real,scheduled;private int session;private float dim=1;private long last,previousFrame,started=SystemClock.elapsedRealtime();private int fps=60,late,frames;private final android.graphics.Paint paint=new android.graphics.Paint(3);private final RectF oval=new RectF();private final Matrix rotation=new Matrix();private Shader shader;private String track="";
 LauncherinCircularView(Context c,LauncherinVisualOptions o){super(c);options=o;setClipChildren(true);setClipToPadding(true);ring=new Ring(c);addView(ring,new LayoutParams(-1,-1));cover=new LauncherinMusicDesign.Image(c,true);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);LayoutParams p=new LayoutParams(1,1,Gravity.CENTER);addView(cover,p);setContentDescription("Visualizador circular de áudio");}
 @Override protected void onMeasure(int w,int h){if(cover!=null){int n=Math.round(Math.min(View.MeasureSpec.getSize(w),View.MeasureSpec.getSize(h))*.58f);LayoutParams p=(LayoutParams)cover.getLayoutParams();p.width=p.height=Math.max(1,n);}super.onMeasure(w,h);}
 @Override protected void onSizeChanged(int w,int h,int ow,int oh){super.onSizeChanged(w,h,ow,oh);shader=new SweepGradient(w/2f,h/2f,colors(),null);}
 private int[] colors(){switch(options.palette){case "cyan":return new int[]{0xff22cfff,0xff81f1ff,0xff22cfff};case "violet":return new int[]{0xff834fff,0xffd69aff,0xff834fff};case "blue":return new int[]{0xff245fff,0xff55b9ff,0xff245fff};default:return new int[]{0xff2169ff,0xff25e0ff,0xffa14fff,0xff2169ff};}}
 void options(LauncherinVisualOptions o){options=o;shader=new SweepGradient(getWidth()/2f,getHeight()/2f,colors(),null);ring.invalidate();}
 void update(int id,boolean playing,boolean minimal,float dim){this.session=id;this.playing=playing;this.minimal=minimal;this.dim=dim;real=spectrum.sync(getContext(),id,active&&isShown()&&playing,minimal,fft->{synchronized(target){LauncherinSpectrum.bands(fft,target);}});if(!real)synchronized(target){java.util.Arrays.fill(target,0);}if(active&&isShown()&&playing&&(real||options.ambient&&options.motion))schedule();else stopFrames();ring.invalidate();}
 String status(){return spectrum.status();}boolean real(){return real;}int targetFps(){return minimal?4:fps;}
 void track(String key){if(!track.equals(key)){track=key;java.util.Arrays.fill(smooth,0);cover.animate().cancel();if(!LauncherinAppearance.get(getContext()).reduced){cover.setAlpha(.45f);cover.animate().alpha(1).setDuration(220).start();}else cover.setAlpha(1);}}
 void activate(boolean value){active=value;if(!active){spectrum.close();stopFrames();cover.animate().cancel();}}
 private void schedule(){if(!scheduled){scheduled=true;int limit=LauncherinAppearance.get(getContext()).reduced?Math.min(15,targetFps()):targetFps();Choreographer.getInstance().postFrameCallbackDelayed(this,limit<=30?Math.max(0,1000/limit-10):0);}}
 private void stopFrames(){if(scheduled)Choreographer.getInstance().removeFrameCallback(this);scheduled=false;last=previousFrame=0;}
 @Override public void doFrame(long now){scheduled=false;if(!active||!isShown()||!playing||!real&&!(options.ambient&&options.motion))return;int limit=LauncherinAppearance.get(getContext()).reduced?Math.min(15,targetFps()):targetFps();if(!minimal&&!LauncherinAppearance.get(getContext()).reduced&&previousFrame>0&&now-previousFrame>1000000000L/fps+25000000L)late++;previousFrame=now;if(!minimal&&++frames==180){if(late>20)fps=Math.max(15,fps/2);frames=late=0;}if(last==0||now-last>=1000000000L/limit){float approach=.22f;synchronized(target){for(int i=0;i<smooth.length;i++)smooth[i]+=((real?target[i]:0)-smooth[i])*approach;}last=now;ring.invalidate();if(options.motion){double t=(SystemClock.elapsedRealtime()-started)/1000.0;float range=Math.min(getWidth(),getHeight())*.025f;ring.setTranslationX((float)Math.sin(t/43)*range);ring.setTranslationY((float)Math.sin(t/57)*range);cover.setTranslationX(ring.getTranslationX());cover.setTranslationY(ring.getTranslationY());}else{ring.setTranslationX(0);ring.setTranslationY(0);cover.setTranslationX(0);cover.setTranslationY(0);}}schedule();}
 @Override protected void onVisibilityChanged(View v,int visibility){super.onVisibilityChanged(v,visibility);if(spectrum!=null){if(!isShown()){spectrum.close();stopFrames();}else if(active)update(session,playing,minimal,dim);}}
 @Override protected void onDetachedFromWindow(){activate(false);super.onDetachedFromWindow();}
 void close(){activate(false);}
 private final class Ring extends View {Ring(Context c){super(c);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}
  @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(cx,cy)*.67f;float strength=options.intensity/100f*dim;paint.setShader(shader);paint.setStrokeCap(Paint.Cap.ROUND);paint.setStyle(Paint.Style.STROKE);oval.set(cx-r,cy-r,cx+r,cy+r);paint.setStrokeWidth(2);paint.setAlpha((int)(150*strength));canvas.drawOval(oval,paint);int stride=minimal?2:1;for(int i=0;i<smooth.length;i+=stride){double a=i*Math.PI*2/smooth.length-Math.PI/2;float length=real?smooth[i]*r*.38f:0;float inside=r+5;float x=(float)Math.cos(a),y=(float)Math.sin(a);paint.setStrokeWidth(minimal?2:3);paint.setAlpha((int)((real?220:options.ambient?65:25)*strength));canvas.drawLine(cx+x*inside,cy+y*inside,cx+x*(inside+2+length),cy+y*(inside+2+length),paint);if(!minimal&&length>1){paint.setStrokeWidth(8);paint.setAlpha((int)(25*strength));canvas.drawLine(cx+x*inside,cy+y*inside,cx+x*(inside+2+length),cy+y*(inside+2+length),paint);}}paint.setShader(null);}
 }
}
